Similar to our thing where we only compile if a submodule is not None (#14533), we could skip compiling the non-taken branch for isinstance checks (since their result is constant) to support use cases like this:
class M(torch.jit.ScriptModule):
    @torch.jit.script_method
    def forward(self, x):
        return x + 2

class N(torch.jit.ScriptModule):
    @torch.jit.script_method
    def forward(self, x):
        return x + 10, x + 100

class Mod(torch.jit.ScriptModule):
    def __init__(self, x):
        super(Mod, self).__init__()
        self.submodule = x

    @torch.jit.script_method
    def forward(self, x):
        res = self.submodule(x)

        if isinstance(res, tuple):
            b = res[1]
        else:
            b = res

        return b
