Simple unit test to show how I get an internal assertion failure when converting from at::Tensor to double.
To Reproduce
Steps to reproduce the behavior:

Compile this code, which tries to convert a vector of IValue to a vector of float

/**
compile and run this gtest to get the internal assertion failure 
(I used `catkin build --make-args tests` inside my ROS package, you could any other tool)
**/
#include "gtest/gtest.h"
#include <ros/package.h>
#include <torch/script.h>
#include <vector>

namespace {
  TEST(TorchTest, TorchTest_TensorIValueCompare_Test) {
    std::vector<float> inputs_vec(21, 1.0);

    // Create a vector of inputs
    torch::Tensor my_tensor = torch::tensor(inputs_vec);
    std::vector<float> v1(my_tensor.data<float>(), my_tensor.data<float>() + my_tensor.numel());

    std::cout << "tensor vector: " << v1 << std::endl;

    //Get vector from blob
    std::vector<torch::jit::IValue> my_jit_vec;
    my_jit_vec.push_back(torch::from_blob(inputs_vec.data(), { 1, 21 }).cuda());
    std::vector<float> v2;

    for (auto i = 0; i < my_jit_vec.size(); i++)
    {
      v2.push_back(my_jit_vec[i].toDouble());
    }
    std::cout << "from blob vector: " << v2 << std::endl;

    EXPECT_EQ(v1, v2);
  }
}

GTEST_API_ int main(int argc, char **argv) {
  printf("Running main() from %s\n", __FILE__);
  testing::InitGoogleTest(&argc, argv);
  return RUN_ALL_TESTS();
}

